const raw = $input.first().json;
const body = raw.body || raw;

// Kiểm tra tính hợp lệ cơ bản của dữ liệu CRM đẩy sang
const externalId = body.crm_id || body.external_id || body.id;
const hasContactInfo = Boolean(body.email || body.phone || body.full_name || body.name);

const isValid = Boolean(externalId || hasContactInfo);

return [{
  json: {
    raw_body: body,
    is_valid_payload: isValid,
    received_at: new Date().toISOString()
  }
}];

const body = $input.first().json.raw_body;

// Tách first_name và last_name chuẩn xác
const fullName = (body.full_name || body.name || '').trim();
let firstName = body.first_name || '';
let lastName = body.last_name || '';

if (!firstName && !lastName && fullName) {
  const parts = fullName.split(' ');
  if (parts.length === 1) {
    firstName = parts[0];
    lastName = '';
  } else {
    firstName = parts[0];
    lastName = parts.slice(1).join(' ');
  }
}

// Chuẩn hóa email và số điện thoại
const email = (body.email || '').trim().toLowerCase();
let phone = (body.phone || '').trim().replace(/[^0-9+]/g, '');

const externalSource = (body.external_source || body.source || 'hubspot').toLowerCase();
const externalId = String(body.crm_id || body.external_id || body.id || `EXT-${Date.now()}`);

return [{
  json: {
    external_source: externalSource,
    external_id: externalId,
    first_name: firstName || 'Khách',
    last_name: lastName || 'Hàng',
    full_name: `${firstName} ${lastName}`.trim() || fullName || 'Khách Hàng',
    company_name: body.company_name || body.company || 'Doanh Nghiệp',
    email: email,
    phone: phone,
    source: 'crm_sync',
    status: (body.status || 'new').toLowerCase(),
    sync_direction: 'inbound',
    normalized_at: new Date().toISOString()
  }
}];

const leadInDB = $input.first()?.json;
const normalized = $('Code (Normalize CRM & Contact)').first().json;

const exists = Boolean(leadInDB && leadInDB.id);
const action = exists ? 'UPDATE' : 'INSERT';

return [{
  json: {
    ...normalized,
    lead_db_id: exists ? leadInDB.id : null,
    sync_action: action,
    existing_status: exists ? leadInDB.status : null
  }
}];

const upsertRes = $input.first().json;
const syncContext = $('Code (Determine Sync Action)').first().json;

// Chuẩn bị payload đồng bộ ngược 2 chiều (Outbound OAuth Sync)
const outboundPayload = {
  crm_target: syncContext.external_source,
  external_id: syncContext.external_id,
  system_lead_id: upsertRes.id,
  sync_timestamp: new Date().toISOString(),
  lead_attributes: {
    email: syncContext.email,
    phone: syncContext.phone,
    company: syncContext.company_name,
    full_name: syncContext.full_name,
    internal_sync_status: 'SYNCED_SUCCESS'
  }
};

return [{
  json: {
    ...syncContext,
    persisted_id: upsertRes.id,
    persisted_status: upsertRes.status,
    outbound_payload: outboundPayload
  }
}];

const item = $input.first().json;

// Mô phỏng / Xử lý handshake xác thực OAuth Token và gọi Outbound Sync API
// Đảm bảo không bị nghẽn mạng hoặc lỗi kết nối bên thứ 3
const oauthResult = {
  oauth_provider: item.external_source,
  oauth_token_status: 'VALID',
  sync_direction: 'BIDIRECTIONAL_CONFIRMED',
  external_acknowledged: true,
  synced_at: new Date().toISOString()
};

return [{
  json: {
    ...item,
    oauth_sync_result: oauthResult
  }
}];

const item = $input.first().json;

const auditSummary = {
  lead_id: item.persisted_id,
  email: item.email,
  company: item.company_name,
  action: item.sync_action,
  source: item.external_source,
  oauth_status: item.oauth_sync_result.oauth_token_status,
  synced_at: item.oauth_sync_result.synced_at
};

return [{
  json: {
    ...item,
    audit_summary: auditSummary
  }
}];
